// PUBLIC-only HTTPS host double for the actual unmodified normal stdin CLI.
import https from'node:https';import{syncBuiltinESMExports}from'node:module';import{EventEmitter}from'node:events';import{createBrowserSourceFixture,canonical,sha}from'./browser-source-v2.fixture.mjs';
if(typeof process.send!=='function')throw Error('PUBLIC_BROWSER_TEST_IPC_REQUIRED');const f=createBrowserSourceFixture();process.once('exit',()=>f.close());
https.request=(url,options,callback)=>{const request=new EventEmitter();request.destroy=error=>{if(error)request.emit('error',error);request.emit('close')};request.end=()=>{queueMicrotask(()=>{try{const u=new URL(url);if(options.method!=='GET')throw Error('PUBLIC_BROWSER_METHOD');let raw,type;const owner=u.pathname.match(/^\/accounts\/(0x[0-9a-f]{40})\/authorization$/)?.[1];if(owner&&u.origin===f.input.node.origin){const record=f.rawRegistrations[owner];if(!record)throw Error('PUBLIC_BROWSER_OWNER');raw=canonical(record);type='registration';}else if(u.origin+u.pathname===f.input.policy.endpoint){if(u.searchParams.get('profile')!==sha(f.profileRaw))throw Error('PUBLIC_BROWSER_PROFILE');raw=f.current(u.searchParams.get('nonce'));type='current';}else throw Error('PUBLIC_BROWSER_URL');process.send({kind:'PUBLIC_BROWSER_HTTP',type});const response=new EventEmitter();response.statusCode=200;response.headers={'content-type':'application/json'};response.complete=false;response.destroy=()=>response.emit('close');callback(response);response.emit('data',Buffer.from(raw));response.complete=true;response.emit('end');response.emit('close');request.emit('close');}catch(error){request.emit('error',error);request.emit('close')}});return request};return request;};syncBuiltinESMExports();process.send({kind:'PUBLIC_BROWSER_INPUT',input:f.input});
